// #83178a (5e9c55c71c45aaa00f83178a) — причина «нет данных» в отчёте: звонок короче 30 с → «השיחה נקטעה בשניות
// הראשונות» везде; звонок ≥30 с без речи кандидата → «המועמד כמעט לא דיבר». Кейсы REP-001, REP-002.
// По ГОТОВЫМ отчётам QA-кандидатов testim от 21.10.2026 (новых звонков нет, OpenAI не тратится): QA-57977a-27s-2110
// (26 с) и QA-83178a-silent-2110 (45 с, молчание). Только чтение → @prod-safe.
import * as path from 'path';
import { test, expect } from '@playwright/test';
import { openReport, explanations, texts } from './support';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const HASH = '#83178a · #5e9c55c71c45aaa00f83178a';
const CUT = 'השיחה נקטעה בשניות הראשונות';
const SILENT = 'המועמד כמעט לא דיבר';
const DOMAINS = 4;
const CHECKPOINTS = 22;

const CASES = [
  { name: process.env.QA_SHORT_CALL_CANDIDATE || 'QA-57977a-27s-2110', what: 'звонок 26 с', expected: CUT, absent: /כמעט לא דיבר/, ac: 'AC1' },
  { name: process.env.QA_SILENT_CALL_CANDIDATE || 'QA-83178a-silent-2110', what: 'звонок 45 с без речи кандидата', expected: SILENT, absent: /נקטעה/, ac: 'AC2' },
];

test.describe(`Отчёт — короткий звонок и молчание кандидата (${HASH})`, () => {
  for (const c of CASES) {
    test(`${c.what} (${c.name}): «${c.expected}» в итоге, 4 доменах и 22 точках @desktop @prod-safe ${HASH}`, async ({ page }) => {
      await openReport(page, c.name);
      const { summary, domains, checkpoints } = explanations(page);
      await expect(domains).toHaveCount(DOMAINS);
      await expect(checkpoints).toHaveCount(CHECKPOINTS);

      // Источник: ${c.ac} — одна и та же причина в итоге, в каждом домене и в каждой точке.
      await expect(summary).toContainText(c.expected);
      const all = [await summary.innerText(), ...(await texts(domains)), ...(await texts(checkpoints))];
      const missing = all.filter((t) => !t.includes(c.expected));
      expect(missing, `объяснения без «${c.expected}»`).toEqual([]);
      const wrong = all.filter((t) => c.absent.test(t));
      expect(wrong, `объяснения с чужой причиной ${c.absent}`).toEqual([]);
    });
  }
});
